import * as THREE from 'three';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Load image texture
  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  const textureMap = ctx.textureLoader.load(imageUrl);

  // Create plane geometry with 512:320 aspect ratio
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Create material using TSL nodes
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(textureMap)
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  mesh.position.set(0, -2.85, 0.2);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Setup user data
  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  return mesh;
}
